def getFileData():
    '''
    Get the filename from the request argument,
    validate the filename,
    and return the data of the file.
    '''
    import os
    from flask import abort
    from werkzeug.utils import secure_filename

    filename = request.args.get("filename")
    if not filename or "\0" in filename:
        abort(400)

    safe_filename = secure_filename(filename)
    if not safe_filename or safe_filename != filename:
        abort(400)

    try:
        base_dir = os.path.realpath(app.config.get("FILE_DIRECTORY", "."))
    except Exception:
        base_dir = os.path.realpath(".")

    file_path = os.path.realpath(os.path.join(base_dir, safe_filename))

    try:
        common_path = os.path.commonpath([base_dir, file_path])
    except ValueError:
        abort(403)

    if os.path.normcase(common_path) != os.path.normcase(base_dir):
        abort(403)

    if not os.path.isfile(file_path):
        abort(404)

    try:
        with open(file_path, "rb") as f:
            return f.read()
    except OSError:
        abort(500)
